parameters.jsCode:
// Compare active workflows against recent executions.
// A workflow that is active but has not finished a run recently is silent.
// n8n does not raise an error for this: nothing failed, nothing ran.

const settings = $('Settings').first().json;
const silentAfterMs = Number(settings.silentAfterMinutes) * 60 * 1000;
const now = Date.now();

const workflows = $('Get active workflows').first().json.data || [];
const executions = $('Get recent executions').first().json.data || [];

// Most recent stoppedAt per workflow id.
const lastRun = {};
for (const e of executions) {
  const id = String(e.workflowId);
  if (!e.stoppedAt) continue;
  const stopped = Date.parse(e.stoppedAt);
  if (!stopped) continue;
  if (!lastRun[id] || stopped > lastRun[id]) lastRun[id] = stopped;
}

// Only workflows with a schedule or interval trigger are expected to run on
// their own. Webhook-driven ones may legitimately sit idle.
const selfStarting = [
  'n8n-nodes-base.scheduleTrigger',
  'n8n-nodes-base.cron',
  'n8n-nodes-base.interval',
];

const silent = [];
for (const w of workflows) {
  const id = String(w.id);

  let scheduled = false;
  const nodes = w.nodes || [];
  for (const n of nodes) {
    if (selfStarting.indexOf(n.type) !== -1) {
      scheduled = true;
      break;
    }
  }
  if (!scheduled) continue;

  const last = lastRun[id];

  // No execution in the retention window is 'unknown', not 'broken'.
  // Reporting it as a failure is how these checks train you to ignore them.
  if (!last) continue;

  const quietFor = now - last;
  if (quietFor > silentAfterMs) {
    silent.push({
      workflowId: id,
      name: w.name,
      lastFinished: new Date(last).toISOString(),
      quietForMinutes: Math.round(quietFor / 60000),
    });
  }
}

if (silent.length === 0) {
  return [{ json: { workflowId: null, name: null, lastFinished: null, quietForMinutes: 0 } }];
}

const out = [];
for (const row of silent) {
  out.push({ json: row });
}
return out;

